#include <iostream>
#include <vector>
#include <cstdint>
#include <string>

// Emulate BGI bar fill with 8x8 custom pattern (caro: 0xAA, 0x55, ...)
void fill_rect(std::vector<std::string>& canvas, int x1, int y1, int x2, int y2, const uint8_t pat[8]) {
    for (int y = y1; y <= y2; ++y) {
        uint8_t row = pat[y % 8];
        for (int x = x1; x <= x2; ++x) {
            // Bit 7 is the leftmost pixel (column offset 0)
            bool bit = (row >> (7 - (x % 8))) & 1;
            canvas[y][x] = bit ? 'X' : '.';
        }
    }
}

int main() {
    // Caro pattern: row 0 is 0xAA (10101010b), row 1 is 0x55 (01010101b)
    const uint8_t caro[8] = {0xAA, 0x55, 0xAA, 0x55, 0xAA, 0x55, 0xAA, 0x55};
    const int width = 10;
    const int height = 6;
    std::vector<std::string> screen(height, std::string(width, ' '));

    // Fill rectangle from (1, 1) to (8, 4)
    fill_rect(screen, 1, 1, 8, 4, caro);

    for (int y = 0; y < height; ++y) {
        std::cout << screen[y] << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <queue>

// Modern C++17 emulation of BGI floodfill algorithm
void floodfill_emu(std::vector<std::string>& canvas, int start_x, int start_y, char fill_char, char border_char) {
    int h = static_cast<int>(canvas.size());
    int w = static_cast<int>(canvas[0].size());
    if (start_x < 0 || start_x >= w || start_y < 0 || start_y >= h) return;
    if (canvas[start_y][start_x] == border_char || canvas[start_y][start_x] == fill_char) return;

    std::queue<std::pair<int, int>> q;
    q.push({start_x, start_y});
    canvas[start_y][start_x] = fill_char;

    const int dx[] = {1, -1, 0, 0};
    const int dy[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [cx, cy] = q.front();
        q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                if (canvas[ny][nx] != border_char && canvas[ny][nx] != fill_char) {
                    canvas[ny][nx] = fill_char;
                    q.push({nx, ny});
                }
            }
        }
    }
}

// Emulate outtextxy writing directly into pixel canvas
void outtextxy_emu(std::vector<std::string>& canvas, int x, int y, const std::string& text) {
    int h = static_cast<int>(canvas.size());
    int w = static_cast<int>(canvas[0].size());
    if (y < 0 || y >= h) return;
    for (size_t i = 0; i < text.size() && (x + static_cast<int>(i)) < w; ++i) {
        if (x + static_cast<int>(i) >= 0) {
            canvas[y][x + i] = text[i];
        }
    }
}

int main() {
    const int width = 16;
    const int height = 7;
    std::vector<std::string> screen(height, std::string(width, ' '));

    // Draw closed rectangle boundary with '*'
    for (int x = 2; x <= 13; ++x) { screen[1][x] = '*'; screen[5][x] = '*'; }
    for (int y = 1; y <= 5; ++y) { screen[y][2] = '*'; screen[y][13] = '*'; }

    // Execute floodfill inside the rectangle with pattern '~' and border '*'
    floodfill_emu(screen, 3, 2, '~', '*');

    // Output text inside filled region: outtextxy(5, 3, "BGI")
    outtextxy_emu(screen, 5, 3, "BGI");

    for (const auto& row : screen) {
        std::cout << row << "\n";
    }
    return 0;
}
